@php
    // Every icon the chain has — the sprite is whatever the layers put in icons/.
    $names = class_exists(\WebxUi\Themes\ThemeIcons::class) ? app(\WebxUi\Themes\ThemeIcons::class)->names() : [];
@endphp
<section @class(['b-showcase-icons', 'b-showcase-icons--'.($view ?: 'grid')]) data-wx-block="showcase-icons">
    @if ($heading)
        <h2 class="b-showcase-icons__heading">{{ $heading }}</h2>
    @endif
    @if ($note)
        <p class="b-showcase-icons__note">{{ $note }}</p>
    @endif
    @if (($view ?: 'grid') === 'grid')
        <ul class="b-showcase-icons__grid">
            @foreach ($names as $name)
                <li class="b-showcase-icons__item">
                    <x-theme::icon :name="$name" class="b-showcase-icons__icon" />
                    <code class="b-showcase-icons__name">{{ $name }}</code>
                </li>
            @endforeach
        </ul>
    @else
        <div class="b-showcase-icons__cases">
            <p class="b-showcase-icons__line"><x-theme::icon name="phone" /> {{ $line }} <x-theme::icon name="arrow-up-right" /></p>
            <p class="b-showcase-icons__sizes">
                <x-theme::icon name="star" />
                <x-theme::icon name="star" class="b-showcase-icons__size-2" />
                <x-theme::icon name="star" class="b-showcase-icons__size-3" />
                <x-theme::icon name="star" class="b-showcase-icons__size-4" label="{{ $label }}" />
            </p>
            <p class="b-showcase-icons__actions">
                <a class="b-showcase-icons__button" href="#">{{ $button }}<x-theme::icon name="arrow-right" /></a>
                <a class="b-showcase-icons__button b-showcase-icons__button--quiet" href="#"><x-theme::icon name="download" />{{ $button }}</a>
            </p>
            <div class="b-showcase-icons__accent">
                <x-theme::icon name="check" /> <x-theme::icon name="info" /> <x-theme::icon name="alert" /> {{ $line }}
            </div>
        </div>
    @endif
</section>

styles:
.b-showcase-icons {
    padding-block: var(--site-space-6);
}

.b-showcase-icons__heading {
    margin: 0 0 var(--site-space-2);
}

.b-showcase-icons__note {
    max-width: 42rem;
    margin: 0 0 var(--site-space-4);
    color: var(--site-color-text-muted);
}

.b-showcase-icons__grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(8rem, 1fr));
    gap: var(--site-space-2);
    margin: 0;
    padding: 0;
    list-style: none;
}

.b-showcase-icons__item {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--site-space-2);
    padding: var(--site-space-3) var(--site-space-2);
    border: 1px solid var(--site-color-border);
    border-radius: var(--site-radius-md);
    background: var(--site-color-surface);
}

.b-showcase-icons__icon {
    width: 1.75em;
    height: 1.75em;
    color: var(--site-color-text);
}

.b-showcase-icons__name {
    font-size: 0.875em;
    color: var(--site-color-text-muted);
    overflow-wrap: anywhere;
    text-align: center;
}

.b-showcase-icons__cases {
    display: grid;
    gap: var(--site-space-4);
}

.b-showcase-icons__cases > * {
    margin: 0;
}

.b-showcase-icons__sizes {
    display: flex;
    align-items: center;
    gap: var(--site-space-3);
    color: var(--site-color-accent);
}

.b-showcase-icons__size-2 {
    width: 1.5em;
    height: 1.5em;
}

.b-showcase-icons__size-3 {
    width: 2em;
    height: 2em;
}

.b-showcase-icons__size-4 {
    width: 3em;
    height: 3em;
}

.b-showcase-icons__actions {
    display: flex;
    flex-wrap: wrap;
    gap: var(--site-space-3);
}

.b-showcase-icons__button {
    display: inline-flex;
    align-items: center;
    gap: var(--site-space-2);
    min-height: 44px;
    padding: var(--site-space-2) var(--site-space-4);
    border: 1px solid var(--site-color-accent);
    border-radius: var(--site-radius-md);
    background: var(--site-color-accent);
    color: var(--site-color-accent-contrast);
    font-weight: 600;
    text-decoration: none;
}

.b-showcase-icons__button--quiet {
    background: transparent;
    color: var(--site-color-accent);
}

.b-showcase-icons__accent {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--site-space-2);
    padding: var(--site-space-4);
    border-radius: var(--site-radius-md);
    background: var(--site-color-accent);
    color: var(--site-color-accent-contrast);
}
